parameters.jsCode:
// Field minimization: only subject + a truncated plain-text body + received_at
// ever leave this workflow toward LLM Gateway (same convention as Action
// Extraction's 'Build extraction prompt'). email_id/account_id/participants/
// is_from_user are carried forward in THIS node's own output json (rather
// than via $('Execute Workflow Trigger') back-references) so later nodes can
// read them without re-resolving the trigger -- picked as the simpler of the
// two allowed conventions, and used consistently by every node below.
const input = $json || {};
const emailId = input.email_id;
const accountId = input.account_id;
const participants = input.participants;
const isFromUser = input.is_from_user === true;

// Malformed input (null/missing subject, body, or received_at) must never
// throw here (mirrors Action Extraction's own field-minimization node).
const subject = input.subject === null || input.subject === undefined ? '' : String(input.subject);
const bodyRaw = input.body === null || input.body === undefined ? '' : String(input.body);
const receivedAt = input.received_at === null || input.received_at === undefined ? '' : String(input.received_at);
const truncatedBody = bodyRaw.slice(0, 2000);

const directionContext = isFromUser
  ? 'This email was SENT by the account owner.'
  : 'This email was RECEIVED by the account owner.';

const systemPrompt = 'You are an email commitment-detection assistant. Read the email and decide whether it contains AT MOST ONE promise-like commitment -- someone explicitly committing to do something for the other party. There are two possible directions: "you-promised" (the account owner is the one making the promise) and "promised-to-you" (the other party is the one making the promise, i.e. a promise made TO the account owner). ' + directionContext + ' Use that fact together with who is actually making the promise in the email text to resolve direction -- do not assume direction from sender alone (a sent email can relay or quote the other party\'s promise, and a received email can restate the account owner\'s own prior promise). If a commitment is found, set has_commitment to true, direction to exactly "you-promised" or "promised-to-you", text to a short paraphrase of the commitment, trigger_sentence to the EXACT verbatim sentence copied from the email body that the detection is based on (it must be a literal substring of the body below, not paraphrased or reworded in any way), confidence to an integer from 0 to 100, and optionally due_date in YYYY-MM-DD format. Today\'s date / the email\'s reference date is ' + receivedAt + '. Only include due_date if a date for the commitment is clearly and confidently stated in the email, or unambiguously implied relative to the reference date above (for example "by Friday") -- resolve any such relative date against the reference date, do not invent one. If you cannot produce a confident due_date in YYYY-MM-DD format, omit the field entirely rather than guess. If no commitment is found, set has_commitment to false and omit every other field entirely. Respond only with JSON matching the given schema.';

const userContent = `Email received: ${receivedAt}\n\nSubject: ${subject}\n\nBody:\n${truncatedBody}`;

// direction/text/trigger_sentence are constrained to plain strings;
// due_date is pinned to YYYY-MM-DD via pattern as defense-in-depth (the
// actual enforcement point is 'Validate extraction result' below, not this
// schema) -- same convention Action Extraction's prompt builder uses for
// its own deadline field.
const responseSchema = {
  type: 'object',
  properties: {
    has_commitment: {
      type: 'boolean',
    },
    direction: {
      type: 'string',
      enum: ['you-promised', 'promised-to-you'],
    },
    text: {
      type: 'string',
    },
    trigger_sentence: {
      type: 'string',
    },
    confidence: {
      type: 'integer',
    },
    due_date: {
      type: 'string',
      pattern: '^\\d{4}-\\d{2}-\\d{2}$',
    },
  },
  required: ['has_commitment'],
};

return {
  json: {
    email_id: emailId,
    account_id: accountId,
    participants: participants,
    is_from_user: isFromUser,
    system_prompt: systemPrompt,
    user_content: userContent,
    response_schema: responseSchema,
  },
};

// Never throws unhandled (same convention as Action Extraction's 'Validate
// extraction result') -- any unexpected error still produces an { outcome:
// 'error', ... } item that routes to the error branch.
try {
  const gatewayResult = $json || {};

  // .first() rather than .item: with multiple items in flight, .item cannot
  // resolve a single unambiguous upstream match and n8n throws 'Multiple
  // matches' -- same convention Action Extraction's 'Validate extraction
  // result' uses (fixed this way after 004-triage hit the bug live).
  let emailId = null;
  let accountId = null;
  let participants = null;
  let isFromUser = null;
  try {
    const built = $('Build extraction prompt').first().json;
    emailId = built.email_id;
    accountId = built.account_id;
    participants = built.participants;
    isFromUser = built.is_from_user;
  } catch (refErr) {
    emailId = null;
  }

  if (!gatewayResult.success) {
    const message = gatewayResult.error || 'LLM Gateway call failed';
    return { json: { outcome: 'error', email_id: emailId, error: String(message) } };
  }

  const data = gatewayResult.data || {};

  // No commitment found is the common, successful case -- no write at all,
  // not an error (mirrors Action Extraction's has_task:false handling).
  if (!data.has_commitment) {
    return { json: { outcome: 'none', email_id: emailId } };
  }

  const direction = data.direction;
  if (direction !== 'you-promised' && direction !== 'promised-to-you') {
    return {
      json: {
        outcome: 'error',
        email_id: emailId,
        error: `direction '${direction}' is not a recognized value`,
      },
    };
  }

  const text = data.text;
  if (typeof text !== 'string' || text.trim().length === 0) {
    return {
      json: {
        outcome: 'error',
        email_id: emailId,
        error: 'has_commitment true but text missing/empty',
      },
    };
  }

  const triggerSentence = data.trigger_sentence;
  if (typeof triggerSentence !== 'string' || triggerSentence.trim().length === 0) {
    return {
      json: {
        outcome: 'error',
        email_id: emailId,
        error: 'has_commitment true but trigger_sentence missing/empty',
      },
    };
  }

  const confidence = data.confidence;
  if (typeof confidence !== 'number' || Number.isNaN(confidence)) {
    return {
      json: {
        outcome: 'error',
        email_id: emailId,
        error: `confidence '${confidence}' is not a number`,
      },
    };
  }

  const dueDate = data.due_date;
  const hasDueDate = dueDate !== undefined && dueDate !== null && dueDate !== '';

  if (hasDueDate) {
    if (typeof dueDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) {
      return {
        json: {
          outcome: 'error',
          email_id: emailId,
          error: `due_date '${dueDate}' does not match YYYY-MM-DD`,
        },
      };
    }
  }

  return {
    json: {
      outcome: 'commitment',
      email_id: emailId,
      account_id: accountId,
      participants: participants,
      is_from_user: isFromUser,
      direction,
      text,
      trigger_sentence: triggerSentence,
      due_date: hasDueDate ? dueDate : null,
      confidence,
    },
  };
} catch (err) {
  let emailId = null;
  try {
    emailId = $('Build extraction prompt').first().json.email_id;
  } catch (refErr) {
    emailId = null;
  }
  return {
    json: {
      outcome: 'error',
      email_id: emailId,
      error: (err && err.message) || 'Unknown Commitment Extraction error',
    },
  };
}

// Never throws -- a missing/malformed participants value produces
// counterparty_email: null rather than blocking the write (spec Edge Cases:
// a commitment with no resolvable counterparty still gets written, with
// counterparty_id resolved to null by 'Write commitment''s subquery).
const input = $json || {};

// participants may arrive as a native array (declared object-shaped input)
// or, if it crossed a boundary that serialized it, as a JSON string --
// accept either, same defensive parsing convention Email Normaliser's
// 'Normalize' node uses for its own object-shaped inputs.
function asArray(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }
  return [];
}

const participants = asArray(input.participants);
const isFromUser = input.is_from_user === true;

function firstAddressForRole(role) {
  const match = participants.find((p) => p && p.role === role && p.address);
  return match ? match.address : null;
}

// is_from_user true: counterparty is the first 'to' participant, falling
// back to the first 'cc' participant if there is no 'to' entry.
// is_from_user false: counterparty is the 'from' participant.
let counterpartyEmail = null;
if (isFromUser) {
  counterpartyEmail = firstAddressForRole('to') || firstAddressForRole('cc');
} else {
  counterpartyEmail = firstAddressForRole('from');
}

return { json: { ...input, counterparty_email: counterpartyEmail } };

parameters.query:
INSERT INTO commitments (email_id, direction, text, trigger_sentence, counterparty_id, due_date, status, confidence)
VALUES (
  $1, $2, $3, $4,
  (SELECT id FROM contacts WHERE account_id = $5 AND email = $6),
  $7, 'open', $8
);

