// .first() rather than .item -- see 'Validate extraction result' node's
// note: .item cannot resolve a single unambiguous upstream match when
// multiple items are in flight.
const emailId = $('Validate extraction result').first().json.email_id;
return { json: { email_id: emailId, extracted: true } };

// No commitment found -- no DB write at all, just a minimal output.
// .first() rather than .item -- see 'Validate extraction result' node's note.
const emailId = $('Validate extraction result').first().json.email_id;
return { json: { email_id: emailId, extracted: false } };

// No error-logging DB write this phase: unlike Action Extraction (which has
// an 'action_extraction_error' column to write to) there is no
// 'commitment_extraction_error' column on emails, and adding one is a schema
// change out of scope for this task -- see Sticky Note. This node simply
// formats the error outcome for the caller instead of a Postgres write.
// .first() rather than .item -- see 'Validate extraction result' node's note.
const emailId = $('Validate extraction result').first().json.email_id;
return { json: { email_id: emailId, extracted: false } };
